<?php

namespace App\Modules\Hrm\Payroll\Payslip;

use App\Models\User;
use App\Modules\Hrm\Models\Payslip;
use Dompdf\Adapter\CPDF;
use Dompdf\Dompdf;
use Dompdf\Options;
use Illuminate\Support\Facades\View;
use Illuminate\Validation\ValidationException;

/**
 * Renders a payslip to PDF under SAL-07's confidentiality controls.
 *
 * SAL-07 ticked every option, and three of the four live here:
 *
 *  - **Watermark** — a fixed-position rotated block the stylesheet repeats on
 *    every page, so it cannot be lost by paging.
 *  - **Generated by / user / time** — stamped into the footer of the document
 *    itself, not merely shown on the screen that produced it. A printed payslip
 *    that turns up somewhere it should not still says where it came from.
 *  - **Password-protected export** — Correction C9b's rule, applied through the
 *    PDF's own encryption rather than a zip around it.
 *
 * The fourth, restricted role access, is enforced at the route: HR by
 * permission, the employee by self-scope, and — per Correction C5 / ACL-02 —
 * Department Managers not at all.
 *
 * ⚠ **A protected export is refused when no password can be formed.** Falling
 * back to an unprotected file, or to a weaker password, would hand out a
 * document that claims a protection it does not have.
 */
class PayslipPdf
{
    public function __construct(private readonly PayslipDocument $document) {}

    /**
     * @throws ValidationException
     */
    public function render(Payslip $payslip, ?User $generatedBy = null, bool $protected = true): string
    {
        $employee = $payslip->employee;
        $password = $employee === null ? null : PayslipPassword::for($employee);

        if ($protected && $password === null) {
            throw ValidationException::withMessages([
                'payslip' => $employee === null
                    ? 'This payslip has no employee attached, so the SAL-07 password cannot be formed.'
                    : PayslipPassword::missingReason($employee),
            ]);
        }

        $options = new Options;
        // Nothing in this document is remote, and a payslip must never be able
        // to reach out of the server while rendering.
        $options->set('isRemoteEnabled', false);
        $options->set('isHtml5ParserEnabled', true);

        // ⚠⚠ THE EARLIER NOTE HERE SAID DOMPDF "REFUSES" A CUSTOM FACE. It does
        // not. It refuses **woff2**, which is the only format Google Fonts
        // serves and therefore the only one the previous attempt had: dompdf
        // parses TrueType and OpenType, nothing else. Point it at a .ttf on
        // disk and it embeds the font perfectly happily, with isRemoteEnabled
        // still false and no other option changed.
        //
        // ⚠ Checked, not assumed: rendering with the font cache deleted still
        // embeds the face, and `chroot` turned out to be irrelevant to the
        // @font-face path, so no extra filesystem access is opened here.
        // OfficialDocumentFontTest asserts the font name appears in the PDF's
        // own font descriptors, which is what a silent fallback would fail.

        // Office Circular BdG-HQ-OD-26071201: Tiro Bangla is the official face
        // for documents that leave the organisation, and a payslip emailed to
        // an employee is one of them.
        //
        // ⚠⚠ IT IS ALSO THE ONLY FONT HERE THAT CAN WRITE BANGLA AT ALL. The
        // previous default, DejaVu Sans, HAS NO BENGALI GLYPHS - an employee
        // whose name is spelled in Bangla came out as a row of empty boxes on
        // their own payslip. That was never a styling preference; it was a
        // document that could not say who it belonged to.
        $options->set('defaultFont', 'Tiro Bangla');

        $options->set('fontCache', $this->fontCacheDirectory());

        $dompdf = new Dompdf($options);
        $dompdf->loadHtml(View::make('hrm.payslip', [
            'doc' => $this->document->build($payslip, $generatedBy),
            'protected' => $protected,
        ])->render());
        $dompdf->setPaper('A4');
        $dompdf->render();

        if ($protected && $password !== null) {
            $canvas = $dompdf->getCanvas();

            if ($canvas instanceof CPDF) {
                // The employee may open and print their own payslip. Modifying
                // and copying stay closed: this is a record, not a draft.
                //
                // The owner password is deliberately not the user's — an owner
                // password equal to the user password lifts the restrictions it
                // is meant to impose.
                $canvas->get_cpdf()->setEncryption(
                    $password,
                    $this->ownerPassword($payslip),
                    ['print'],
                );
            }
        }

        return (string) $dompdf->output();
    }

    public function filename(Payslip $payslip): string
    {
        return sprintf(
            'payslip-%s-%s.pdf',
            strtolower((string) ($payslip->employee?->employee_code ?? $payslip->employee_id)),
            str_replace(' ', '-', strtolower((string) ($payslip->run?->period?->label() ?? 'period'))),
        );
    }

    /**
     * A per-document owner password nobody needs to know and nobody can guess.
     * It exists only so the permission flags above actually bind.
     */
    private function ownerPassword(Payslip $payslip): string
    {
        return hash('sha256', sprintf('%s|%s|%s', config('app.key'), $payslip->id, $payslip->created_at));
    }

    /**
     * Where dompdf may write its parsed-font cache.
     *
     * ⚠ Its default is inside the vendor directory, which is read-only on a
     * deployed container and is wiped by every composer install. Pointing it at
     * storage means the first payslip after a deploy pays the parsing cost once
     * rather than failing.
     */
    private function fontCacheDirectory(): string
    {
        $path = storage_path('app/dompdf-fonts');

        if (! is_dir($path)) {
            mkdir($path, 0775, true);
        }

        return $path;
    }
}
